-- As a DBA user
CREATE USER sales IDENTIFIED BY "Sales#2026"
  QUOTA 10M ON users;
GRANT CREATE SESSION, CREATE TABLE TO sales;

CREATE USER app_user IDENTIFIED BY "App#2026";
GRANT CREATE SESSION, CREATE PROCEDURE, CREATE SYNONYM TO app_user;

CREATE ROLE orders_reader;
GRANT orders_reader TO app_user;

-- Connected as SALES
CREATE TABLE orders (
  order_id     NUMBER PRIMARY KEY,
  customer     VARCHAR2(50),
  amount       NUMBER(10,2),
  order_date   DATE
);

INSERT INTO orders VALUES (1, 'Asha',  2500, DATE '2026-11-01');
INSERT INTO orders VALUES (2, 'Ravi',  1200, DATE '2026-11-02');
INSERT INTO orders VALUES (3, 'Meena',  800, DATE '2026-11-03');
COMMIT;

SELECT owner, object_name, object_type, status
  FROM dba_objects
 WHERE UPPER(object_name) = 'ORDERS';

SELECT role, owner, table_name, privilege
  FROM role_tab_privs
 WHERE table_name = 'ORDERS';

-- Connected as APP_USER
CREATE SYNONYM orders FOR sales.orders;

SELECT order_id, customer, amount FROM orders;

CREATE OR REPLACE PROCEDURE count_orders IS
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM sales.orders;
  DBMS_OUTPUT.PUT_LINE('Orders: ' || v_count);
END;
/
SHOW ERRORS

-- Connected as SALES
GRANT SELECT ON orders TO app_user;

-- Connected as APP_USER
ALTER PROCEDURE count_orders COMPILE;
SET SERVEROUTPUT ON
EXEC count_orders

SELECT owner, synonym_name, table_owner, table_name, db_link
  FROM all_synonyms
 WHERE synonym_name = 'ORDERS';

BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE orders_stage PURGE';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -942 THEN
      RAISE;
    END IF;
END;
/

